const lessons = [...baseLessons, ...extendedLessons, ...supplementalLessons, ...courseDeepLessons].map((lesson, index) => ({ ...lesson, _order: index })).sort((a, b) => tracksSortOrder(a.track, b.track) || levelOrder[a.level] - levelOrder[b.level] || a._order - b._order).map(({ _order, ...lesson }) => lesson)
function tracksSortOrder(a, b) { return a.localeCompare(b) }
const levels = ['All levels', 'Basic', 'Intermediate', 'Advanced']
const tracks = ['All topics', ...new Set(lessons.map((lesson) => lesson.track))]

